import * as React from "react";
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'
import Lightbox from 'yet-another-react-lightbox'
import 'yet-another-react-lightbox/styles.css'

import "../scss/main.scss";

import Header from "../components/Header";
import Footer from "../components/Footer";

interface ImageSharpEdge {
  node: {
    publicURL: string
    childImageSharp: {
      thumb: IGatsbyImageData
      full: IGatsbyImageData
    }
  }
}

interface ImageNode {
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    images: {
      edges: ImageSharpEdge[]
    }
    pictureMeLogo: {
      nodes: ImageNode[]
    }
    circlesLogo: {
      nodes: ImageNode[]
    }
  }
}

const DeveloperPage: React.FC<PageProps> = ({ data }) => {
  const [lightboxIndex, setLightboxIndex] = React.useState(-1)

  // Transform images for lightbox
  const lightboxSlides = data.images.edges.map(({ node }) => {
    return {
      src: node.publicURL,
    }
  })

  const logoImage = data.pictureMeLogo.nodes[0]
    ? getImage(data.pictureMeLogo.nodes[0].childImageSharp.thumb)
    : null

  const circlesLogo = data.circlesLogo.nodes[0]
    ? getImage(data.circlesLogo.nodes[0].childImageSharp.thumb)
    : null

  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <h1>Developer</h1>
        <p>Building digital solutions with clean code and innovative thinking — transforming ideas into reality.</p>
        <div className="accent-line"></div>
      </div>
      <div className="case-study-card-wrap">
        <Link to="/developer/picture-me" className="case-study-card">
          {logoImage && (
            <div className="case-study-card__logo-wrap">
              <GatsbyImage
                image={logoImage}
                alt="Picture Me"
                className="case-study-card__logo"
              />
            </div>
          )}
          <div className="case-study-card__info">
            <h3>Picture Me</h3>
            <p>A full-stack MEAN app — an interactive photo mosaic representing the layers of a person.</p>
          </div>
        </Link>
      </div>
      <div className="case-study-card-wrap">
        <Link to="/developer/circles-game" className="case-study-card">
          {circlesLogo && (
            <div className="case-study-card__logo-wrap">
              <GatsbyImage
                image={circlesLogo}
                alt="Circles Game"
                className="case-study-card__logo"
              />
            </div>
          )}
          <div className="case-study-card__info">
            <h3>Circles Game</h3>
            <p>A visual memory game — memorise the coloured circle sequence and repeat it back.</p>
          </div>
        </Link>
      </div>
      {data.images.edges.length > 0 && (
        <>
          <div className="masonry-gallery">
            {data.images.edges.map(({ node }, index) => {
              const image = getImage(node.childImageSharp.thumb)
              if (!image) return null

              return (
                <div
                  key={index}
                  className="gallery-item"
                  onClick={() => setLightboxIndex(index)}
                >
                  <GatsbyImage
                    image={image}
                    alt={`Developer - Image ${index + 1}`}
                    className="gallery-thumb"
                  />
                </div>
              )
            })}
          </div>
          <Lightbox
            open={lightboxIndex >= 0}
            close={() => setLightboxIndex(-1)}
            index={lightboxIndex}
            slides={lightboxSlides}
          />
        </>
      )}
      <Footer />
    </div>
  );
}

export const pageQuery = graphql`
  query DeveloperImagesQuery {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { nin: ["picture-me", "circles-game"] }
      }
      sort: { name: ASC }
    ) {
      edges {
        node {
          publicURL
          childImageSharp {
            thumb: gatsbyImageData(
              width: 600
              placeholder: BLURRED
              aspectRatio: 1
            )
            full: gatsbyImageData(layout: FULL_WIDTH)
          }
        }
      }
    }
    pictureMeLogo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "picture-me" }
        name: { eq: "picture-me-logo-small" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(width: 600, placeholder: BLURRED)
        }
      }
    }
    circlesLogo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "circles-game" }
        name: { eq: "colour_game_logo_small" }
      }
    ) {
      nodes {
        childImageSharp {
          thumb: gatsbyImageData(width: 600, placeholder: BLURRED)
        }
      }
    }
  }
`

export default DeveloperPage;
